from pathlib import Path
import html,json
from PIL import Image
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'tools/projects.json').read_text())
O=json.loads((R/'tools/original-projects.json').read_text())
E=html.escape
P=''

def img(path,alt='',cls='',eager=False,zoom=False):
 with Image.open(R/path) as im:w,h=im.size
 tag=f'<img src="{P}{path}?v=34" alt="{E(alt)}" class="{cls}" width="{w}" height="{h}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
 if zoom:return f'<a class="zoom" href="{P}{path}" data-zoom data-caption="{E(alt)}" aria-label="Рассмотреть: {E(alt)}">{tag}<span class="zoom-label" aria-hidden="true">Рассмотреть ↗</span></a>'
 return tag

def decor(name,cls=''):
 return f'<span class="decor-object {cls}" aria-hidden="true">{img("assets/img/decor/object-"+name+".webp","")}</span>'

def divider(name='ribbons'):
 return ''

def mascot(pose='urban-neutral',cls='',live=False):
 return f'<div class="mascot-scene {cls}" data-default-pose="{pose}"'+(' data-mascot' if live else '')+f'><div class="mascot-body">{img("assets/img/mascot/"+pose+".webp","","mascot-image",pose=="urban-neutral")}</div></div>'

def btn(href,text,kind='solid',attrs=''):
 return f'<a class="button {kind}" href="{href}" {attrs}>{text}<span aria-hidden="true">↗</span></a>'

def head(title,desc):
 return f'<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f6f3ef"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><meta property="og:locale" content="ru_RU"><link rel="icon" href="{P}assets/favicon.svg"><link rel="preload" href="{P}assets/fonts/manrope-regular.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="{P}assets/css/styles.css?v=34"><script src="{P}assets/js/main.js?v=34" defer></script></head>'

def header(home=False):
 b='' if home else P+'index.html'
 return f'<a class="skip" href="#main">К содержанию</a><header class="site-header"><div class="wrap header-row"><a class="brand" href="{b}#home" aria-label="Диана Тхайцухова — главная">soulminori<span aria-hidden="true">✳</span></a><nav aria-label="Основная навигация"><a href="{b}#projects">Проекты</a><a href="{b}#workshop">Хуторок</a><a href="{b}#about">Обо мне</a></nav><a class="header-contact" href="{b}#contact">Написать ↗</a><button type="button" class="motion-toggle" aria-pressed="false" aria-label="Отключить анимацию" title="Отключить анимацию">Ⅱ</button></div></header>'

